<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import type { Api } from './api'
import AssessmentRadar from './AssessmentRadar.vue'
const props = defineProps<{api: Api; manage: boolean; assign: boolean; talentId?: string}>()
interface Question {id:string;version:number;enabled:boolean;content:QuestionForm}
interface QuestionForm {title:string;kind:string;options:{id:string;text:string}[];correct:string[];dimension:string;points:number}
interface Paper {id:string;title:string;version:number;versions:{id:string;number:number;snapshot:{title:string}}[]}
interface Task {id:string;title:string;name:string;state:string;paper_number:number}
interface Detail extends Task {version:number;own:boolean;draft:Record<string,string[]>;final_answers:Record<string,string[]>|null;questions:({id:string}&QuestionForm)[];result:{total:number;maximum:number;dimensions:Record<string,{score:number;maximum:number}>}|null;error_code:string|null}
const tasks=ref<Task[]>([]), total=ref(0), offset=ref(0), questions=ref<Question[]>([]), papers=ref<Paper[]>([])
const employees=ref<{id:string;name:string;username:string}[]>([]), detail=ref<Detail|null>(null), busy=ref(false)
const form=ref<QuestionForm>(empty()), editing=ref<Question|null>(null), enabled=ref(true), showQuestion=ref(false)
const paper=ref({title:'',question_ids:[] as string[],paper_id:null as string|null,version:null as number|null})
const publishedChoices=ref<{id:string;number:number;title:string}[]>([])
const assignment=ref({paper_version_id:'',employee_id:''}), answers=ref<Record<string,string[]>>({})
const states:Record<string,string>={pending:'待参与',answering:'作答中',submitted:'已提交，待评分',completed:'已完成'}
function addOption(){form.value.options.push({id:crypto.randomUUID(),text:''})}
function empty():QuestionForm {return {title:'',kind:'single',options:[{id:'a',text:''},{id:'b',text:''}],correct:[],dimension:'',points:10}}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function load(){const p=await props.api<{items:Task[];total:number}>(`/assessments/assignments?offset=${offset.value}&limit=20${props.talentId?'&talent_id='+props.talentId:''}`);tasks.value=p.items;total.value=p.total;if(props.manage){questions.value=await props.api('/assessments/questions');papers.value=await props.api('/assessments/papers')}if(props.assign){employees.value=await props.api('/assessments/employees');publishedChoices.value=await props.api('/assessments/published-choices')}}
function editQuestion(q?:Question){editing.value=q||null;form.value=q?JSON.parse(JSON.stringify(q.content)):empty();enabled.value=q?.enabled??true;showQuestion.value=true}
async function saveQuestion(){await run(async()=>{const q=editing.value;await props.api('/assessments/questions'+(q?'/'+q.id:''),q?'PUT':'POST',{...form.value,enabled:enabled.value,...(q?{version:q.version}:{})});showQuestion.value=false;await load()})}
async function publish(){await run(async()=>{await props.api('/assessments/papers','POST',paper.value,crypto.randomUUID());await load();ElMessage.success('已保存不可变发布版本')})}
async function assignTask(){await run(async()=>{await props.api('/assessments/assignments','POST',assignment.value,crypto.randomUUID());await load();ElMessage.success('测评已分配')})}
async function open(t:Task){await run(async()=>{detail.value=await props.api('/assessments/assignments/'+t.id);answers.value=JSON.parse(JSON.stringify(detail.value!.final_answers||detail.value!.draft));for(const q of detail.value!.questions)answers.value[q.id]??=[]})}
async function save(submit=false){const d=detail.value!;if(submit){const missing=d.questions.filter(q=>!answers.value[q.id]?.length).length;try{await ElMessageBox.confirm(`${missing?'还有 '+missing+' 道题未答，未答计零分。':''}提交后答案锁定，是否提交？`,'提交测评',{type:'warning',confirmButtonText:'确定',cancelButtonText:'继续答题'})}catch{return}}await run(async()=>{detail.value=await props.api(`/assessments/assignments/${d.id}/${submit?'submit':'draft'}`,submit?'POST':'PUT',{version:d.version,answers:answers.value});await load();ElMessage.success(submit?'最终答案已保存':'草稿已保存')})}
async function score(){await run(async()=>{detail.value=await props.api(`/assessments/assignments/${detail.value!.id}/score`,'POST');await load()})}
onMounted(()=>run(load))
</script>
<template>
  <section><div class="title-row"><div><h1>轻量测评</h1><p class="muted">只反映指定试卷、指定时间的测得表现，不自动计入岗位匹配分。</p></div><el-button @click="run(load)">刷新</el-button></div>
    <el-tabs v-if="manage && !talentId"><el-tab-pane label="题库维护"><el-button @click="editQuestion()">新增题目</el-button><el-table :data="questions"><el-table-column prop="content.title" label="题目"/><el-table-column prop="content.dimension" label="能力维度"/><el-table-column prop="version" label="版本"/><el-table-column label="状态"><template #default="s">{{s.row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button @click="editQuestion(s.row)">编辑 / 停用</el-button></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="试卷发布"><p>发布会复制题目、答案和评分规则；后续修改题库不影响历史任务。</p><el-form label-position="top"><el-form-item label="试卷（留空为新建）"><el-select v-model="paper.paper_id" clearable @change="(id: string)=>{const p=papers.find(p=>p.id===id);paper.version=p?.version??null;paper.title=p?.title||''}"><el-option v-for="p in papers" :key="p.id" :value="p.id" :label="p.title"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="paper.title"/></el-form-item><el-form-item label="题目"><el-select v-model="paper.question_ids" multiple><el-option v-for="q in questions.filter(q=>q.enabled)" :key="q.id" :value="q.id" :label="q.content.title"/></el-select></el-form-item><el-button :loading="busy" @click="publish">发布新版本</el-button></el-form><el-table :data="papers"><el-table-column prop="title" label="试卷"/><el-table-column prop="version" label="最新版本"/></el-table></el-tab-pane></el-tabs>
    <el-card v-if="assign && !talentId"><h3>分配测评</h3><el-select v-model="assignment.paper_version_id" placeholder="发布版本"><el-option v-for="v in publishedChoices" :key="v.id" :value="v.id" :label="`${v.title} · v${v.number}`"/></el-select><el-select v-model="assignment.employee_id" placeholder="授权内已绑定员工"><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="`${e.name} (${e.username})`"/></el-select><el-button :loading="busy" @click="assignTask">分配</el-button></el-card>
    <h3>测评任务与历史</h3><el-table :data="tasks"><el-table-column prop="title" label="试卷"/><el-table-column prop="name" label="人才"/><el-table-column prop="paper_number" label="试卷版本"/><el-table-column label="状态"><template #default="s">{{states[s.row.state]}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button @click="open(s.row)">答题 / 查看</el-button></template></el-table-column></el-table><el-empty v-if="!tasks.length" description="未测评：暂无当前权限内的测评任务"/><el-pagination layout="total, prev, pager, next" :total="total" :page-size="20" @current-change="(n: number)=>{offset=(n-1)*20;run(load)}"/>
    <el-drawer v-if="detail" :model-value="!!detail" @close="detail=null" size="min(760px,95vw)" title="测评答题与结果"><template v-if="detail"><h2>{{detail.title}} · v{{detail.paper_number}}</h2><p>{{states[detail.state]}}</p><div v-for="q in detail.questions" :key="q.id"><h3>{{q.title}}（{{q.points}}分）</h3><p class="muted">维度：{{q.dimension}}</p><el-checkbox-group v-if="q.kind==='multiple'" v-model="answers[q.id]" :disabled="!detail.own || !['pending','answering'].includes(detail.state)"><el-checkbox v-for="o in q.options" :key="o.id" :value="o.id">{{o.text}}</el-checkbox></el-checkbox-group><el-radio-group v-else :model-value="answers[q.id]?.[0]" @update:model-value="(v: unknown)=>answers[q.id]=[String(v)]" :disabled="!detail.own || !['pending','answering'].includes(detail.state)"><el-radio v-for="o in q.options" :key="o.id" :value="o.id">{{o.text}}</el-radio></el-radio-group></div><p v-if="detail.own && ['pending','answering'].includes(detail.state)"><el-button :loading="busy" @click="save()">保存草稿</el-button><el-button type="primary" :loading="busy" @click="save(true)">提交并锁定答案</el-button></p><el-button v-if="detail.state==='submitted'" :loading="busy" @click="score">恢复评分（保留原提交）</el-button><el-card v-if="detail.result"><h3>成绩 {{detail.result.total}} / {{detail.result.maximum}}</h3><AssessmentRadar :dimensions="detail.result.dimensions"/><p>仅展示本次实际测得的维度；其他能力为未测评。</p><div v-for="(d,name) in detail.result.dimensions" :key="name"><span>{{name}}：{{d.score}} / {{d.maximum}}</span><el-progress :percentage="Math.round(d.score/d.maximum*100)"/></div></el-card></template></el-drawer>
    <el-dialog v-model="showQuestion" title="维护题目" width="min(700px,95vw)"><el-form label-position="top"><el-form-item label="题干"><el-input v-model="form.title" type="textarea"/></el-form-item><el-form-item label="题型"><el-select v-model="form.kind" @change="form.correct=[]"><el-option label="单选" value="single"/><el-option label="多选（完全正确得分）" value="multiple"/><el-option label="判断（两个选项）" value="boolean"/></el-select></el-form-item><el-form-item label="维度"><el-input v-model="form.dimension"/></el-form-item><el-form-item label="分值"><el-input-number v-model="form.points" :min="1" :max="100"/></el-form-item><div v-for="(o,i) in form.options" :key="o.id" class="file-row"><span>{{o.id}}</span><el-input v-model="o.text" placeholder="选项内容"/><el-button @click="form.options.splice(i,1);form.correct=form.correct.filter(c=>c!==o.id)">移除</el-button></div><el-button @click="addOption">增加选项</el-button><el-form-item label="标准答案（仅题库管理可见）"><el-select v-model="form.correct" multiple><el-option v-for="o in form.options" :key="o.id" :value="o.id" :label="o.text||o.id"/></el-select></el-form-item><el-switch v-model="enabled" active-text="启用" inactive-text="停用"/></el-form><template #footer><el-button :loading="busy" @click="saveQuestion">保存题目</el-button></template></el-dialog>
  </section>
</template>
